"""Build Mike's candidate picker. Contains no game runtime integration."""
from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
A=R/'_ART_SOURCES/monster_mutator_1003'
data=json.loads((A/'roster.json').read_text(encoding='utf-8'))
cards=[]
for a in data['candidates']:
 h=lambda s:html.escape(s,quote=True)
 cards.append(f'''<article class="card" data-id="{a['id']}" data-name="{h(a['name'])}">
 <div class="specimen"><span class="number">{a['id']}</span><button class="inspect" data-inspect="{a['id']}" aria-label="Inspect {h(a['name'])}"><img src="{a['output']}" alt="{h(a['name'])} mutated drone candidate"></button></div>
 <div class="info"><div class="role">{h(a['role'])}</div><h2>{h(a['name'])}</h2><p>{h(a['behavior'])}</p><p class="tell"><strong>Attack cue</strong> {h(a['tell'])}</p>
 <div class="actions"><button class="pick" aria-pressed="false" data-pick="{a['id']}">+ Shortlist</button><a href="{a['output']}" target="_blank" rel="noopener">Full PNG ↗</a></div>
 <details><summary>Original fusion pairing</summary><img class="ref" loading="lazy" src="{a['reference_copy']}" alt="Original pairing for {h(a['name'])}"></details></div></article>''')
page=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Monster Mutator · Candidate Lab</title><link rel="icon" href="data:,"><style>
:root{color-scheme:dark;--bg:#090d0c;--panel:#141b18;--line:#2c3731;--green:#b9ff58;--muted:#9fad9f;--white:#f1f1de}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--white);font:16px/1.5 system-ui,Segoe UI,sans-serif}header,main,footer{max-width:1490px;margin:auto;padding:0 34px}header{padding-top:32px}.mast{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;font:11px monospace;letter-spacing:.14em;color:var(--muted)}.mast b{color:var(--green)}.hero{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:45px 0 35px;align-items:center}.kicker{font:12px monospace;letter-spacing:.18em;color:var(--green)}h1{font-size:clamp(40px,5.4vw,78px);letter-spacing:-.055em;line-height:.96;margin:20px 0 24px;font-weight:900}h1 span{color:var(--green)}.intro{color:#b8c0b4;max-width:510px;font-size:17px}.hero-art{display:flex;align-items:center;justify-content:center;min-height:260px;position:relative}.hero-art img{width:66%;max-height:365px;object-fit:contain}.hero-art img+img{width:47%;margin-left:-20%;margin-top:95px}.small-label{font:11px monospace;color:var(--muted);margin-top:21px}.toolbar{position:sticky;top:0;z-index:10;display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 0;background:#090d0cf5;border-top:1px solid var(--line);border-bottom:1px solid var(--line);backdrop-filter:blur(10px)}button,select,a{font:inherit}button,select{border:1px solid #435344;background:#19241c;color:var(--white);border-radius:4px;padding:9px 14px;cursor:pointer}button:hover{border-color:var(--green)}button:focus-visible,a:focus-visible,select:focus-visible{outline:2px solid var(--green);outline-offset:4px}.filter.active{background:var(--green);color:#111a0b;border-color:var(--green)}.toolbar label{font-size:13px;color:var(--muted);margin-left:auto}.count{font:12px monospace;color:var(--green)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin-top:25px}.card{background:var(--panel);border:1px solid var(--line);border-radius:9px;overflow:hidden;display:flex;flex-direction:column}.card.selected{border-color:var(--green);box-shadow:0 0 0 1px var(--green)}.specimen{height:300px;position:relative;background:radial-gradient(ellipse at 50% 70%,#263228 0,#121b16 52%,#0c120f 85%);display:flex;align-items:center;justify-content:center;border-bottom:1px solid var(--line)}.number{position:absolute;top:17px;left:18px;color:var(--green);font:13px monospace;z-index:2}.inspect{width:100%;height:100%;padding:22px;border:0;background:transparent}.inspect img{width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.compact .inspect img{width:96px;height:96px}.compact .inspect{display:flex;align-items:center;justify-content:center}.info{padding:23px;flex:1;display:flex;flex-direction:column}.role{color:var(--green);font:10px monospace;text-transform:uppercase;letter-spacing:.12em}h2{font-size:28px;line-height:1.1;letter-spacing:-.03em;margin:10px 0 13px}.info p{font-size:14px;color:#c1c7bd;margin:0 0 16px}.info .tell{font-size:12px;color:#99aa9c;min-height:54px}.tell strong{color:#d8ddcd;display:block;text-transform:uppercase;font:10px monospace;margin-bottom:5px}.actions{margin-top:auto;display:flex;gap:15px;align-items:center}.pick{flex:1;font-size:13px}.selected .pick{color:#14200b;background:var(--green);border-color:var(--green)}a{color:#bccbab;text-decoration:none;font-size:12px}a:hover{text-decoration:underline}details{border-top:1px solid var(--line);margin-top:18px;padding-top:13px;font-size:12px;color:var(--muted)}summary{cursor:pointer}.ref{display:block;max-width:100%;max-height:400px;margin:18px auto;background:#fff}.empty{display:none;color:var(--muted);padding:45px;text-align:center}.selection{margin:35px 0;padding:25px;border:1px solid var(--line);border-radius:9px;background:#111913}.selection h2{font-size:22px}.selection p{color:var(--muted);font-size:13px}.selection textarea{width:100%;min-height:95px;background:#080d0a;color:var(--white);border:1px solid var(--line);padding:14px;resize:vertical;font:13px monospace}.selection button{margin-top:10px}.selection span{font-size:12px;color:var(--green);padding:10px}footer{border-top:1px solid var(--line);padding-top:24px;padding-bottom:35px;color:var(--muted);font:11px/1.8 monospace}dialog{max-width:95vw;max-height:95vh;background:#0c150e;color:var(--white);border:1px solid #60724d;border-radius:10px;padding:20px}dialog::backdrop{background:#000c}dialog img{display:block;max-width:85vw;max-height:75vh;object-fit:contain}dialog header{display:flex;padding:0;justify-content:space-between;align-items:center;gap:25px}dialog h2{font-size:23px}dialog button{padding:8px 12px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hero-art img{width:80%}.hero-art img+img{width:55%;margin-left:-32%}}@media(max-width:620px){header,main,footer{padding-left:18px;padding-right:18px}.hero{grid-template-columns:1fr;padding-top:28px}.hero-art{min-height:170px}.hero-art img{max-height:220px;width:60%}.hero-art img+img{margin-top:40px;width:45%;margin-left:-15%}.grid{grid-template-columns:1fr}.toolbar label{margin-left:0}.specimen{height:310px}.mast{font-size:9px}.intro{font-size:15px}}
</style></head><body><header><div class="mast"><b>BULLETS OF FURY / MONSTER MUTATOR</b><span>SPECIMEN SET 001 · 15 CANDIDATES</span></div><section class="hero"><div><div class="kicker">MACHINE + MONSTER</div><h1>Choose what<br><span>survives.</span></h1><p class="intro">Your drone pairings, mutated into fifteen new enemies. Bone, armor, corrupted reactors and inherited weapons. Pick the ones worth bringing to life.</p><div class="small-label">CONCEPT SPRITES · PROPOSED ATTACKS · AWAITING YOUR PICKS</div></div><div class="hero-art"><img src="01-cacoforge.png" alt="Cacoforge"><img src="14-revenant-relay.png" alt="Revenant Relay"></div></section></header><main><nav class="toolbar" aria-label="Candidate filters"><button class="filter active" data-filter="all">All 15</button><button class="filter" data-filter="picked">Shortlist</button><span class="count" id="count">0 selected</span><label>Preview <select id="size"><option value="large">Large</option><option value="small">96 px silhouette</option></select></label></nav><div class="grid">__CARDS__</div><div class="empty">Your shortlist is empty. Add candidates from the full roster.</div><section class="selection"><h2>Your selection</h2><p>Saved in this browser. Copy the list back into chat when you are ready to choose.</p><textarea id="selection" aria-label="Selected candidate names" readonly></textarea><button id="copy">Copy shortlist</button><span id="copy-status" role="status"></span></section></main><footer>Generated from Mike's 15 reference pairings with built-in image generation. Static candidate art; attack descriptions are proposals. No enemies from this set have been added to the game. Modular parts and animation sheets come after selection.</footer><dialog id="zoom"><header><h2 id="zoom-name"></h2><button id="close">Close</button></header><img id="zoom-art" alt=""></dialog><script>
const key='bof-mutator-1003-shortlist';const cards=[...document.querySelectorAll('.card')];let saved=[];try{saved=JSON.parse(localStorage.getItem(key)||'[]')}catch(e){}const selected=new Set(Array.isArray(saved)?saved:[]);let filter='all';const count=document.getElementById('count'),selection=document.getElementById('selection');
function refresh(){let visible=0;for(const card of cards){const yes=selected.has(card.dataset.id),button=card.querySelector('.pick');card.classList.toggle('selected',yes);button.setAttribute('aria-pressed',String(yes));button.textContent=yes?'✓ Shortlisted':'+ Shortlist';card.hidden=filter==='picked'&&!yes;card.style.display=card.hidden?'none':'';if(!card.hidden)visible++}const chosen=cards.filter(c=>selected.has(c.dataset.id));count.textContent=chosen.length+' selected';selection.value=chosen.length?'Monster Mutator picks:\n'+chosen.map(c=>c.dataset.id+' — '+c.dataset.name).join('\n'):'No candidates selected yet.';document.querySelector('.empty').style.display=visible?'none':'block';try{localStorage.setItem(key,JSON.stringify([...selected]))}catch(e){}}
for(const button of document.querySelectorAll('[data-pick]'))button.addEventListener('click',()=>{const id=button.dataset.pick;selected.has(id)?selected.delete(id):selected.add(id);refresh()});for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x===button));refresh()});document.getElementById('size').addEventListener('change',e=>document.querySelector('.grid').classList.toggle('compact',e.target.value==='small'));
document.getElementById('copy').addEventListener('click',async()=>{const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText(selection.value);status.textContent='Copied.'}catch(e){selection.focus();selection.select();status.textContent='Select and copy the text above.'}});
const zoom=document.getElementById('zoom');for(const button of document.querySelectorAll('[data-inspect]'))button.addEventListener('click',()=>{const card=button.closest('.card'),img=card.querySelector('.inspect img');document.getElementById('zoom-name').textContent=card.dataset.id+' / '+card.dataset.name;document.getElementById('zoom-art').src=img.src;document.getElementById('zoom-art').alt=img.alt;zoom.showModal()});document.getElementById('close').onclick=()=>zoom.close();zoom.addEventListener('click',e=>{if(e.target===zoom)zoom.close()});refresh();
</script></body></html>'''.replace('__CARDS__',''.join(cards))
(A/'roster.html').write_text(page,encoding='utf-8')
O=R/'_shots/monster_mutator_1003';O.mkdir(exist_ok=True)
# A base URL makes the scratch review consume the same preserved originals.
(O/'review.html').write_text(page.replace('<head>','<head><base href="../../_ART_SOURCES/monster_mutator_1003/">',1),encoding='utf-8')
print('Built 15-card picker and portable roster.html; no runtime imports.')
